var e={configEditor:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Leggi la configurazione live della stampante direttamente da Moonraker - ogni file, analizzato in sezioni e parametri, con i problemi strutturali segnalati. Per ora in sola lettura; la modifica guidata arriverà prossimamente.`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Aiuto`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Informazioni sull'Editor di Configurazione`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Chiudi`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Come si usa`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Scegli un file di configurazione dal menu a tendina - printer.cfg è selezionato per impostazione predefinita.`}},{t:0,b:{t:2,i:[{t:3}],s:`Sfoglia le sezioni; clicca su una per espanderne i parametri.`}},{t:0,b:{t:2,i:[{t:3}],s:`Controlla il banner di Validazione per problemi strutturali come una sezione duplicata.`}},{t:0,b:{t:2,i:[{t:3}],s:`Passa a Grezzo per leggere il testo esatto del file.`}}],topics:{sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`Sezioni e parametri`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Una configurazione Klipper è un elenco di blocchi [section], ciascuno contenente parametri chiave: valore. Questo widget analizza ogni sezione - incluse quelle con un nome come [tmc2209 stepper_x] - ed elenca i suoi parametri con il valore e ogni eventuale commento in linea. I valori multi-riga (come il gcode: di una macro) vengono mantenuti intatti.`}}},includes:{title:{t:0,b:{t:2,i:[{t:3}],s:`File inclusi`}},body:{t:0,b:{t:2,i:[{t:3}],s:`printer.cfg spesso richiama altri file con [include other.cfg] (o un glob come [include configs/*.cfg]). Ogni include è mostrato come voce a sé stante; scegli il file incluso dal menu a tendina per ispezionare ciò che definisce.`}}},validation:{title:{t:0,b:{t:2,i:[{t:3}],s:`Validazione`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Dopo l'analisi, la configurazione viene controllata per problemi strutturali che sono errati indipendentemente dal tipo di sezione - un'intestazione di sezione duplicata, un nome di sezione vuoto, o un parametro che si trova al di fuori di qualsiasi sezione. Questi compaiono nel banner di Validazione; non modificano il file.`}}},saveConfig:{title:{t:0,b:{t:2,i:[{t:3}],s:`Il blocco SAVE_CONFIG`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Klipper aggiunge un blocco generato automaticamente alla fine di printer.cfg (dopo il marcatore #*#) quando esegui SAVE_CONFIG - risultati di calibrazione come PID e offset Z. Viene mostrato ma contrassegnato come salvato automaticamente, ed è escluso dal conteggio delle sezioni modificabili perché non dovresti modificarlo manualmente.`}}},readonly:{title:{t:0,b:{t:2,i:[{t:3}],s:`Sola lettura (per ora)`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Questa prima versione legge e mostra soltanto la configurazione - nulla viene scritto sulla stampante. La modifica guidata con conferma (con un backup automatico prima di ogni salvataggio e un riavvio successivo) arriverà in un aggiornamento futuro.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossario`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{section:{term:{t:0,b:{t:2,i:[{t:3}],s:`Sezione`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Un blocco [header] che raggruppa impostazioni correlate, es. [stepper_x] o [extruder].`}}},parameter:{term:{t:0,b:{t:2,i:[{t:3}],s:`Parametro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Una riga chiave: valore (o chiave = valore) all'interno di una sezione, opzionalmente con un commento finale #.`}}},include:{term:{t:0,b:{t:2,i:[{t:3}],s:`[include]`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Una direttiva che richiama un altro file di configurazione in printer.cfg, così le impostazioni possono essere suddivise su più file.`}}},saveConfig:{term:{t:0,b:{t:2,i:[{t:3}],s:`SAVE_CONFIG`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Il blocco generato automaticamente (dopo #*#) dove Klipper memorizza i risultati di calibrazione - non modificarlo manualmente.`}}}}},file:{label:{t:0,b:{t:2,i:[{t:3}],s:`File di configurazione`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`Seleziona un file…`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Aggiorna`}},loadingList:{t:0,b:{t:2,i:[{t:3}],s:`Caricamento dei file…`}},emptyList:{t:0,b:{t:2,i:[{t:3}],s:`Nessun file di configurazione trovato sulla stampante.`}}},summary:{sections:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` sezioni`}]}},params:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` parametri`}]}},size:{t:0,b:{t:2,i:[{t:4,k:`kb`},{t:3,v:` KB`}]}}},validation:{title:{t:0,b:{t:2,i:[{t:3}],s:`Validazione`}},clean:{t:0,b:{t:2,i:[{t:3}],s:`Nessun problema strutturale rilevato.`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Errore`}},warning:{t:0,b:{t:2,i:[{t:3}],s:`Avviso`}}},view:{structured:{t:0,b:{t:2,i:[{t:3}],s:`Strutturato`}},raw:{t:0,b:{t:2,i:[{t:3}],s:`Grezzo`}},expandAll:{t:0,b:{t:2,i:[{t:3}],s:`Espandi tutto`}},collapseAll:{t:0,b:{t:2,i:[{t:3}],s:`Comprimi tutto`}}},section:{saveBadge:{t:0,b:{t:2,i:[{t:3}],s:`salvato automaticamente`}},noParams:{t:0,b:{t:2,i:[{t:3}],s:`(nessun parametro)`}},paramsCount:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` parametri`}]}},paramHead:{t:0,b:{t:2,i:[{t:3}],s:`Parametro`}},valueHead:{t:0,b:{t:2,i:[{t:3}],s:`Valore`}}},edit:{hint:{t:0,b:{t:2,i:[{t:3}],s:`Modifica il testo grezzo qui sotto, poi Salva. Viene creato un backup con marca temporale prima di ogni scrittura.`}}},save:{button:{t:0,b:{t:2,i:[{t:3}],s:`Salva`}},saving:{t:0,b:{t:2,i:[{t:3}],s:`Salvataggio…`}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:`Modifiche non salvate`}},revert:{t:0,b:{t:2,i:[{t:3}],s:`Annulla`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Salvare sulla stampante?`}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:`Questo sovrascrive `},{t:4,k:`file`},{t:3,v:` sulla stampante. Viene salvato prima un backup con marca temporale, ed è necessario un riavvio del firmware per applicare la modifica.`}]}},ack:{t:0,b:{t:2,i:[{t:3}],s:`Capisco che questo scrive sulla stampante`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Salva`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annulla`}},done:{t:0,b:{t:2,i:[{t:3,v:`Salvato. Backup: `},{t:4,k:`backup`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Rifiutato: la stampante è occupata (in stampa o in pausa). Riprova quando è inattiva.`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Salvataggio non riuscito.`}},stale:{t:0,b:{t:2,i:[{t:3}],s:`Il file è cambiato sul disco da quando è stato caricato (potrebbe essere arrivato un SAVE_CONFIG, o un'altra app lo ha modificato). Salvare ora sovrascriverebbe quella modifica - ricarica per controllare (la cronologia dei backup mostra le differenze).`}},staleReload:{t:0,b:{t:2,i:[{t:3}],s:`Ricarica il file`}}},restart:{prompt:{t:0,b:{t:2,i:[{t:3}],s:`Riavviare il firmware per applicare la modifica?`}},button:{t:0,b:{t:2,i:[{t:3}],s:`Riavvia firmware`}},restarting:{t:0,b:{t:2,i:[{t:3}],s:`Riavvio…`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Riavviare il firmware?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`FIRMWARE_RESTART ricarica la configurazione e interrompe brevemente la stampante. Eseguilo solo quando è inattiva.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Riavvia ora`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annulla`}},done:{t:0,b:{t:2,i:[{t:3}],s:`Riavvio del firmware richiesto.`}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Rifiutato: la stampante è occupata. Riavvia quando è inattiva.`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Riavvio non riuscito.`}}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Lettura della configurazione…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Impossibile leggere la configurazione dalla stampante.`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`Riprova`}}},catalog:{title:{t:0,b:{t:2,i:[{t:3}],s:`Aggiungi un blocco di configurazione dal catalogo`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`Scegli un componente - il suo blocco Klipper accurato per l'hardware (run_current, sense_resistor, nomi dei pin reali) viene aggiunto al file per consentirti di rivederlo e salvarlo.`}},drivers:{t:0,b:{t:2,i:[{t:3}],s:`Driver`}},motors:{t:0,b:{t:2,i:[{t:3}],s:`Motori`}},boards:{t:0,b:{t:2,i:[{t:3}],s:`Schede`}},pickPlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Cerca nel catalogo…`}},inserted:{t:0,b:{t:2,i:[{t:3,v:`Blocco inserito per `},{t:4,k:`name`},{t:3,v:` - rivedilo in Grezzo e salva.`}]}},noSnippet:{t:0,b:{t:2,i:[{t:3,v:`Nessun blocco di configurazione disponibile per `},{t:4,k:`name`},{t:3,v:`.`}]}}},drift:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cosa sta eseguendo Klipper`}},pending:{t:0,b:{t:2,i:[{t:3}],s:`Klipper ha modifiche non salvate (un SAVE_CONFIG è in sospeso) - salvare questo file ora le cancellerebbe. Esegui prima SAVE_CONFIG nella console.`}},warningsTitle:{t:0,b:{t:2,i:[{t:3}],s:`Avvisi di configurazione Klipper`}},count:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` valore/i sul disco differiscono da quanto in esecuzione (modificati ma senza FIRMWARE_RESTART):`}]}},adopt:{t:0,b:{t:2,i:[{t:3}],s:`adotta live`}}},pinDoctor:{title:{t:0,b:{t:2,i:[{t:3,v:`Pin Doctor - `},{t:4,k:`n`},{t:3,v:` rilevamento/i di cablaggio`}]}},conflict:{t:0,b:{t:2,i:[{t:3}],s:`CONFLITTO`}},caveat:{t:0,b:{t:2,i:[{t:3}],s:`AVVERTENZA`}}},tmc:{review:{t:0,b:{t:2,i:[{t:3}],s:`rivedi in Grezzo e salva`}}},pinEdit:{offBoard:{t:0,b:{t:2,i:[{t:3}],s:`non sulla scheda`}},offBoardHint:{t:0,b:{t:2,i:[{t:3}],s:`Questo pin non è nella mappa dei pin nota della scheda - controlla un errore di battitura o un pin EXP/virtuale.`}},double:{t:0,b:{t:2,i:[{t:3}],s:`riutilizzato`}},doubleHint:{t:0,b:{t:2,i:[{t:3}],s:`Questo pin è assegnato in più di una sezione.`}},caveat:{t:0,b:{t:2,i:[{t:3}],s:`avvertenza`}}},project:{title:{t:0,b:{t:2,i:[{t:3}],s:`Progetto (include e ricerca)`}},lintBadge:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` problema/i`}]}},searchPlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Cerca in ogni file di configurazione…`}},searchBtn:{t:0,b:{t:2,i:[{t:3}],s:`Cerca`}},noResults:{t:0,b:{t:2,i:[{t:3}],s:`Nessuna corrispondenza.`}},matchesCount:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` corrispondenza/e`}]}},truncated:{t:0,b:{t:2,i:[{t:3}],s:`vengono mostrati i primi risultati`}},tree:{t:0,b:{t:2,i:[{t:3}],s:`Albero degli include`}},missing:{t:0,b:{t:2,i:[{t:3}],s:`file mancante`}},lint:{t:0,b:{t:2,i:[{t:3}],s:`Controlli tra file`}},rule:{broken_include:{t:0,b:{t:2,i:[{t:3}],s:`Include interrotto: `}},orphan_driver:{t:0,b:{t:2,i:[{t:3}],s:`Driver orfano - nessuna sezione corrispondente: `}},section_override:{t:0,b:{t:2,i:[{t:3}],s:`Sovrascrittura (definita in più file, vince l'ultima): `}}}},knowledge:{viewDriver:{t:0,b:{t:2,i:[{t:3,v:`Vedi `},{t:4,k:`model`},{t:3,v:` nel catalogo →`}]}},stepper:{t:0,b:{t:2,i:[{t:3}],s:`Un asse a motore passo-passo - i suoi pin del driver, distanza di rotazione, microstep e homing/finecorsa.`}},tmc:{t:0,b:{t:2,i:[{t:3}],s:`Un driver passo-passo Trinamic - corrente di esercizio/mantenimento, microstep e regolazione StallGuard/chopper per il suo motore.`}},extruder:{t:0,b:{t:2,i:[{t:3}],s:`L'hotend e l'estrusore - dimensione dell'ugello, percorso del filamento, riscaldatore, termistore e PID.`}},heater_bed:{t:0,b:{t:2,i:[{t:3}],s:`Il piano riscaldato - il suo pin del riscaldatore, termistore e limiti PID/temperatura.`}},fan:{t:0,b:{t:2,i:[{t:3}],s:`La ventola di raffreddamento del pezzo che raffredda il filamento appena stampato.`}},heater_fan:{t:0,b:{t:2,i:[{t:3}],s:`Una ventola legata a un riscaldatore (es. raffreddamento dell'hotend) che funziona per proteggerlo dal surriscaldamento.`}},controller_fan:{t:0,b:{t:2,i:[{t:3}],s:`Una ventola che raffredda i driver passo-passo / l'elettronica mentre i motori sono attivi.`}},mcu:{t:0,b:{t:2,i:[{t:3}],s:`Una scheda a microcontrollore che esegue Klipper - la sua connessione seriale o CAN.`}},printer:{t:0,b:{t:2,i:[{t:3}],s:`Cinematica globale della macchina e limiti di movimento (tipo, velocità massima, accelerazione).`}},bed_mesh:{t:0,b:{t:2,i:[{t:3}],s:`Livellamento automatico del piano - sonda una griglia e compensa la planarità del piano durante la stampa.`}},probe:{t:0,b:{t:2,i:[{t:3}],s:`La sonda Z usata per rilevare la superficie del piano per l'homing e la mesh del piano.`}},gcode_macro:{t:0,b:{t:2,i:[{t:3}],s:`Una macro G-code personalizzata - un comando con nome richiamabile dalla console o da altre macro.`}},output_pin:{t:0,b:{t:2,i:[{t:3}],s:`Un pin di uscita controllabile (un LED, relè o linea di abilitazione, per esempio).`}},neopixel:{t:0,b:{t:2,i:[{t:3}],s:`LED RGB indirizzabili (NeoPixel / WS2812) e il loro controllo del colore.`}},board_pins:{t:0,b:{t:2,i:[{t:3}],s:`Alias intuitivi per i pin fisici di una scheda, referenziati altrove nella configurazione.`}},input_shaper:{t:0,b:{t:2,i:[{t:3}],s:`Compensazione delle risonanze che riduce ringing e ghosting alle velocità più elevate.`}},safe_z_home:{t:0,b:{t:2,i:[{t:3}],s:`Esegue l'homing di Z in una posizione XY sicura (spesso il centro del piano) per proteggere l'ugello e il piano.`}},z_tilt:{t:0,b:{t:2,i:[{t:3}],s:`Regola più motori Z in modo che il piano del portale/letto sia livellato.`}},quad_gantry_level:{t:0,b:{t:2,i:[{t:3}],s:`Livella un portale a quattro punti in modo che sia parallelo al piano.`}},filament_switch_sensor:{t:0,b:{t:2,i:[{t:3}],s:`Un sensore di esaurimento filamento che mette in pausa la stampa quando il filamento finisce.`}},virtual_sdcard:{t:0,b:{t:2,i:[{t:3}],s:`Permette a Klipper di stampare i file caricati sull'host (richiesto da Mainsail e Fluidd).`}}},backups:{title:{t:0,b:{t:2,i:[{t:3,v:`Backup (`},{t:4,k:`n`},{t:3,v:`)`}]}},diff:{t:0,b:{t:2,i:[{t:3}],s:`Differenza`}},hideDiff:{t:0,b:{t:2,i:[{t:3}],s:`Nascondi differenza`}},restore:{t:0,b:{t:2,i:[{t:3}],s:`Ripristina`}},diffHint:{t:0,b:{t:2,i:[{t:3}],s:`differenza rispetto al file corrente`}},unchanged:{t:0,b:{t:2,i:[{t:3,v:`⋯ `},{t:4,k:`n`},{t:3,v:` righe invariate ⋯`}]}},note:{t:0,b:{t:2,i:[{t:3}],s:`Le istantanee vengono scritte automaticamente prima di ogni salvataggio. Ripristina ne carica una nell'editor per una revisione finale + salvataggio.`}}},sanity:{title:{t:0,b:{t:2,i:[{t:3,v:`Verifica di plausibilità dei valori driver (`},{t:4,k:`n`},{t:3,v:`)`}]}},note:{t:0,b:{t:2,i:[{t:3,v:`Controllate `},{t:4,k:`n`},{t:3,v:` sezione/i driver TMC. Un driver senza limite massimo curato e un motore passo-passo senza motore assegnato vengono saltati, non stimati.`}]}},rule:{over_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A supera il limite massimo di fondo scala del driver di ~`},{t:4,k:`cap`},{t:3,v:` A.`}]}},near_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A è entro il 10% del limite massimo del driver di ~`},{t:4,k:`cap`},{t:3,v:` A.`}]}},over_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A supera il valore nominale di `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},near_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A è entro il 10% del valore nominale di `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},odd_microsteps:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: microsteps `},{t:4,k:`microsteps`},{t:3,v:` non è una potenza di due (1…256).`}]}}}},panels:{failed:{t:0,b:{t:2,i:[{t:3,v:`Alcuni pannelli non sono stati caricati e sono nascosti: `},{t:4,k:`panels`},{t:3,v:`. Ciò che verificherebbero è sconosciuto al momento - non necessariamente a posto.`}]}},name:{drift:{t:0,b:{t:2,i:[{t:3}],s:`Disco-vs-live`}},pinDoctor:{t:0,b:{t:2,i:[{t:3}],s:`Dottore dei pin`}},sanity:{t:0,b:{t:2,i:[{t:3}],s:`Plausibilità driver`}},project:{t:0,b:{t:2,i:[{t:3}],s:`Vista progetto`}},pinMap:{t:0,b:{t:2,i:[{t:3}],s:`Suggerimenti pin`}},backups:{t:0,b:{t:2,i:[{t:3}],s:`Backup`}},lint:{t:0,b:{t:2,i:[{t:3}],s:`Analisi config`}}}},addPart:{title:{t:0,b:{t:2,i:[{t:3}],s:`Aggiungi un componente (consapevole dei pin liberi)`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`Scegli un tipo di componente e uno dei pin della scheda che NESSUNO usa ancora (letti live dalla tua configurazione + mappa della scheda), e ottieni una sezione pronta scritta attraverso il filtro di sicurezza - nessuna ipotesi sui pin.`}},kind:{t:0,b:{t:2,i:[{t:3}],s:`Tipo di componente`}},name:{t:0,b:{t:2,i:[{t:3}],s:`Nome`}},namePh:{t:0,b:{t:2,i:[{t:3}],s:`es. chamber_fan`}},mcu:{t:0,b:{t:2,i:[{t:3}],s:`Scheda (MCU)`}},pin:{t:0,b:{t:2,i:[{t:3}],s:`Pin libero`}},pinPh:{t:0,b:{t:2,i:[{t:3}],s:`Scegli un pin libero…`}},noFree:{t:0,b:{t:2,i:[{t:3}],s:`Nessun pin libero con nome su questa mappa della scheda.`}}},lint:{title:{t:0,b:{t:2,i:[{t:3,v:`Analisi config — `},{t:4,k:`n`},{t:3,v:` problema/i rilevato/i`}]}},note:{t:0,b:{t:2,i:[{t:3,v:`Controllate `},{t:4,k:`n`},{t:3,v:` sezioni. Solo controlli strutturali; usa gli avvisi di configurazione di Klipper.`}]}},rule:{double_assigned_pin:{t:0,b:{t:2,i:[{t:3,v:`Il pin `},{t:4,k:`pin`},{t:3,v:` è assegnato in più sezioni (`},{t:4,k:`sections`},{t:3,v:`). Il firmware restart fallirà.`}]}},pin_caveat:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: pin `},{t:4,k:`pin`},{t:3,v:` — `},{t:4,k:`message`}]}},klipper_warning:{t:0,b:{t:2,i:[{t:3,v:`Klipper: `},{t:4,k:`message`}]}},save_config_pending:{t:0,b:{t:2,i:[{t:3}],s:`È in sospeso una calibrazione SAVE_CONFIG non salvata. Riavvia per applicarla.`}},missing_printer:{t:0,b:{t:2,i:[{t:3}],s:`Nessuna sezione [printer] trovata — Klipper non si avvierà senza di essa.`}},no_stepper:{t:0,b:{t:2,i:[{t:3}],s:`Nessuna sezione stepper o extruder trovata.`}},heater_temp_range:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: min_temp (`},{t:4,k:`min_temp`},{t:3,v:`) non è inferiore a max_temp (`},{t:4,k:`max_temp`},{t:3,v:`).`}]}}}}}};export{e as default};